; popsum.asm -- chapter 12: a table added up with POP
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "popsum.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
sums    EQU RAM_START          ; 8 sums of two bytes
keep    EQU VARS               ; a word of RAM for SP
TABLE   EQU $D000
; A table of 2,048 words (0, 1, 2 ...) added up with POP, 4 times with
; the interrupt off and 4 times with it on.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        VDP_REG 1, $A0          ; the display off, its interrupt on
        im 1
        ld hl, TABLE            ; the table: word k is k
        ld de, 0
        ld bc, 2048
mk1:    ld (hl), e
        inc hl
        ld (hl), d
        inc hl
        inc de
        dec bc
        ld a, b
        or c
        jr nz, mk1
        ld ix, sums
        ld b, 4
off:    call sumup              ; the interrupt off
        djnz off
        ei
e0:     ld b, 4
on:     call sumup              ; the interrupt on
        djnz on
        di
e1:     nop
stop:   jr stop

; sumup: the 2,048 words added up with POP; the sum stored at IX,
;        IX moved on. Keeps B.
sumup:  ld (keep), sp           ; the real stack, for later
        ld sp, TABLE            ; SP at the start of the table
        ld hl, 0
        ld c, 8
        ld a, b
        ld b, 0                 ; 8 x 256 words
su1:    pop de                  ; the next word, and SP moves on by 2
        add hl, de
        djnz su1
        dec c
        jr nz, su1
        ld b, a
        ld sp, (keep)           ; the real stack back
        ld (ix+0), l
        ld (ix+1), h
        inc ix
        inc ix
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
